# AUTO-GENERATED by Claude Code
# Purpose: Search smash-tube.com (an index of Smash Ultimate match videos on YouTube) by
# player, character, free text and region, and return the videos as pydantic models. The
# result page is server-rendered PHP: each video is plain HTML, so httpx2 + bs4 works.
# Usage: `search_videos(player_1="Sparg0", char_1="cloud")`
# (see `scripts/smashtube_videos.py`).
# ---------------------------------------------------------------------------
# TODO: look in making better how AI should query (to get best match for given question)
#
# Site notes: context the code doesn't show (findings, decisions, dead ends), as of Nov 2026.
# Re-check against the live site if parsing breaks.
#
# How the site behaves:
# - Search is the home page's GET form (`page_id` starts at 1):
#   /en/result?player1=&character1=&player2=&character2=&free_word=&region=&page_id=
#   10 videos per page, at most 50 pages; the count line reads eg
#   "500+ videos found (1 / 50)", so past 500 the real total is unknown.
# - Each video is a `div.rsg`: `img.v-modal[data-video]` is the YouTube id, `data-title` the
#   title, `.Pdate` the upload date (YYYY-MM-DD), `.playerTag a` the player tags ("#Sparg0").
#   Thumbnails are YouTube's own (img.youtube.com/vi/<id>/mqdefault.jpg), so we build them.
# - Characters are sent as their Japanese names, even on /en (the page's `window.charaDict`
#   maps Japanese -> English for display). Echo fighters share one entry (eg
#   "Samus/Dark Samus") and the three Pokemon are one "Pokemon Trainer", hence
#   `SITE_CHARACTER` maps several char ids to the same name. The dict also has non-character
#   categories (System/Tech, Strategy, Clips, Fan Art, Tournament, Variety) we don't expose.
# - Which characters are in a video is only in its title text, eg
#   "Neo (Corrin) vs Sparg0 (Cloud)", in whatever format the uploader used; we return the
#   title as is and don't parse it.
# - Regions are the form's own options: Japan, NA, EU, Other. `free_word` is capped at 20
#   characters.
# - A request without browser-like headers gets "403 Access denied" from the result page (the
#   home page still loads). With a browser User-Agent and a Referer it works.
# - robots.txt: `User-agent: *` is allowed with content signals search=yes, ai-train=no;
#   named AI crawlers (GPTBot, ClaudeBot, ...) are disallowed. Terms of service not reviewed.
#
# Decisions:
# - The user confirmed this use (their own searches through their own agent, one page per
#   call) and the browser User-Agent, same as for supermajor.gg. Keep it to on-demand
#   searches: no crawling of result pages in bulk, no storing the index.
# - Returns pydantic models, not polars (structured objects for the agent tools and the app's
#   video view). Convert with pl.DataFrame([v.model_dump() for v in result.videos]) if needed.
# - We skip the tweets and ads on the page; only the video list is read.
#
# Verified live (Nov 2026): player-only, character-only (500+ for little_mac), two characters
# (joker + little_mac: 146 videos), and the empty result, whose count line is
# "0 videos found (1 / 0)". Region and `page_id` > 1 are built from the form, not checked yet.
# A character name in a player field finds nothing (player1=Joker + a character -> 0 videos):
# the agent tool (ds.ai.smashtube) moves such a name to a character field by default.
from __future__ import annotations

import datetime as dt
import re
from typing import Literal, get_args

import httpx2
from bs4 import BeautifulSoup
from pydantic import BaseModel, Field, computed_field

# A regular desktop Chrome UA, so requests look like a normal browser visit
USER_AGENT = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Safari/537.36"
HOME_URL = "https://smash-tube.com/en"
RESULT_URL = "https://smash-tube.com/en/result"
VIDEOS_PER_PAGE = 10
MAX_SEARCH_TERM_CHARS = 20  # the form's own maxlength
Region = Literal["Japan", "NA", "EU", "Other"]
REGIONS: tuple[str, ...] = get_args(Region)

# 'N videos found (page / pages)', N possibly '500+'
_COUNT_RE = re.compile(r"([\d,]+\+?)\s+videos?\s+found\s*\(\s*(\d+)\s*/\s*(\d+)\s*\)")

