class MatchVideo(BaseModel):
    """One YouTube match video from a smash-tube.com search"""

    video_id: str = Field(description="YouTube video id, eg '57I2f-kKk10'")
    title: str = Field(description="Video title as uploaded; usually names the players, characters and event")
    date: dt.date | None = Field(None, description="Upload date")
    players: list[str] = Field(default_factory=list, description="Player tags the site attached to the video")

    @computed_field
    @property
    def url(self) -> str:
        """Link to watch on YouTube"""
        return f"https://www.youtube.com/watch?v={self.video_id}"

    @computed_field
    @property
    def thumbnail_url(self) -> str:
        """YouTube's 320x180 thumbnail"""
        return f"https://img.youtube.com/vi/{self.video_id}/mqdefault.jpg"

    @property
    def embed_url(self) -> str:
        """Player url for an <iframe> (no cookies until played)"""
        return f"https://www.youtube-nocookie.com/embed/{self.video_id}"


class VideoQuery(BaseModel):
    """The search as sent; empty string = not filtered on"""

    player_1: str = ""
    player_2: str = ""
    char_1: str = Field("", description="SmashDb char id, eg 'little_mac'")
    char_2: str = Field("", description="SmashDb char id, eg 'cloud'")
    search_term: str = ""
    region: str = Field("", description="One of Japan, NA, EU, Other")


class MatchVideos(BaseModel):
    """One page of a smash-tube.com video search"""

    query: VideoQuery
    total: str = Field(description="Videos matching the search as the site reports it; '500+' means more than 500")
    page: int = Field(description="This page's number, from 1")
    pages: int = Field(description="Pages available (10 videos each, the site stops at 50)")
    videos: list[MatchVideo]
    source_url: str = Field(description="The smash-tube.com page these came from")


def site_character(char_id: str) -> str:
    """The site's name for a SmashDb char id ('' stays '')."""
    if not char_id:
        return ""
    if char_id not in SITE_CHARACTER:
        raise ValueError(f"no smash-tube.com character for char id {char_id!r}")
    return SITE_CHARACTER[char_id]


def search_params(query: VideoQuery, page: int = 1) -> dict[str, str]:
    """The result page's query string for a search."""
    if query.region and query.region not in REGIONS:
        raise ValueError(f"region must be one of {list(REGIONS)}, got {query.region!r}")
    if len(query.search_term) > MAX_SEARCH_TERM_CHARS:
        raise ValueError(f"search_term is limited to {MAX_SEARCH_TERM_CHARS} characters by the site")
    if page < 1:
        raise ValueError("page starts at 1")
    params = {
        "player1": query.player_1,
        "character1": site_character(query.char_1),
        "player2": query.player_2,
        "character2": site_character(query.char_2),
        "free_word": query.search_term,
        "region": query.region,
    }
    return params | ({"page_id": str(page)} if page > 1 else {})


def fetch_result_page(params: dict[str, str]) -> tuple[str, str]:
    """(final url, html) of a result page."""
    resp = httpx2.get(
        RESULT_URL,
        params=params,
        # without browser-like headers the result page answers 403 (see Site notes)
        headers={"User-Agent": USER_AGENT, "Referer": HOME_URL, "Accept-Language": "en"},
        timeout=30,
        follow_redirects=True,
    )
    resp.raise_for_status()
    return str(resp.url), resp.text


def _parse_date(text: str) -> dt.date | None:
    try:
        return dt.date.fromisoformat(text.strip())
    except ValueError:
        return None


def parse_videos(html: str) -> tuple[str, int, int, list[MatchVideo]]:
    """(total, page, pages, videos) from a result page's HTML."""
    soup = BeautifulSoup(html, "html.parser")
    result = soup.select_one("#result")
    if result is None:
        raise ValueError("no #result section on the page (smash-tube.com layout changed?)")
    videos: list[MatchVideo] = []
    for box in result.select("div.rsg"):
        holder = box.select_one("[data-video]")
        if holder is None:
            continue
        date = box.select_one(".Pdate")
        videos.append(
            MatchVideo(
                video_id=str(holder["data-video"]),
                title=str(holder.get("data-fulltitle") or holder.get("data-title") or "").strip(),
                date=_parse_date(date.get_text()) if date else None,
                players=[a.get_text(strip=True).lstrip("#") for a in box.select(".playerTag a")],
            )
        )
    message = result.select_one(".resultmsg")
    count = _COUNT_RE.search(message.get_text(" ", strip=True)) if message else None
    if count:
        # an empty result reads '0 videos found (1 / 0)': report it as one (empty) page
        return count[1], int(count[2]), max(int(count[3]), 1), videos
    # no count line: an empty result (or a changed layout, which the video list still survives)
    return str(len(videos)), 1, 1, videos


def search_videos(
    player_1: str = "",
    player_2: str = "",
    char_1: str = "",
    char_2: str = "",
    search_term: str = "",
    region: str = "",
    page: int = 1,
) -> MatchVideos:
    """Search smash-tube.com; every filter is optional, but at least one is needed.

    Args:
        player_1: a player's tag, eg 'Sparg0'.
        player_2: their opponent's tag, eg 'acola'.
        char_1: SmashDb char id of a character in the match, eg 'little_mac'.
        char_2: SmashDb char id of the other character, eg 'cloud'.
        search_term: free text matched against the video (eg an event name), 20 chars at most.
        region: 'Japan', 'NA', 'EU' or 'Other'.
        page: result page, from 1 (10 videos each).
    """
    query = VideoQuery(
        player_1=player_1.strip(),
        player_2=player_2.strip(),
        char_1=char_1,
        char_2=char_2,
        search_term=search_term.strip(),
        region=region,
    )
    if not any(query.model_dump().values()):
        raise ValueError("give at least one of player_1, player_2, char_1, char_2, search_term, region")
    url, html = fetch_result_page(search_params(query, page))
    total, current, pages, videos = parse_videos(html)
    return MatchVideos(query=query, total=total, page=current, pages=pages, videos=videos, source_url=url)
